    13	    public static int Run(string[] args, TextWriter stderr, Stream outputStream)
    14	    {
    15	        if (args.Length != 1)
    16	        {
    17	            stderr.WriteLine("Usage: slice <csv-file>");
    18	            return 1;
    19	        }
    20	
    21	        try
    22	        {
    23	            CsvRoundTripper.CopyFileToStandardOutput(args[0], outputStream);
    24	            return 0;
    25	        }
    26	        catch (Exception ex) when (ex is IOException or UnauthorizedAccessException or ArgumentException)
    27	        {
    28	            stderr.WriteLine(ex.Message);
    29	            return 1;
    30	        }
    31	    }
    32	}
    33	
    34	public static class CsvRoundTripper
    35	{
    36	    public static void CopyFileToStandardOutput(string path, Stream output)
    37	    {
    38	        using var input = File.OpenRead(path);
    39	        input.CopyTo(output);
    40	        output.Flush();
    41	    }
    42	}

