     1	using System.Text;
     2	using Slice;
     3	
     4	var tests = new List<(string Name, Action Test)>
     5	{
     6	    ("copies csv bytes unchanged", CopiesCsvBytesUnchanged),
     7	    ("returns failure when missing file argument", ReturnsFailureWhenMissingFileArgument),
     8	};
     9	
    10	var failures = 0;
    11	
    12	foreach (var (name, test) in tests)
    13	{
    14	    try
    15	    {
    16	        test();
    17	        Console.WriteLine($"PASS {name}");
    18	    }
    19	    catch (Exception ex)
    20	    {
    21	        failures++;
    22	        Console.Error.WriteLine($"FAIL {name}: {ex.Message}");
    23	    }
    24	}
    25	
    26	return failures == 0 ? 0 : 1;
    27	
    28	static void CopiesCsvBytesUnchanged()
    29	{
    30	    var tempPath = Path.Combine(Path.GetTempPath(), Guid.NewGuid().ToString("N") + ".csv");
    31	    var originalBytes = Encoding.UTF8.GetBytes("name,age\r\nAda,36\r\nGrace,47\r\n");
    32	    File.WriteAllBytes(tempPath, originalBytes);
    33	
    34	    try
    35	    {
    36	        using var output = new MemoryStream();
    37	        CsvRoundTripper.CopyFileToStandardOutput(tempPath, output);
    38	
    39	        var copiedBytes = output.ToArray();
    40	        if (!originalBytes.SequenceEqual(copiedBytes))
    41	        {
    42	            throw new Exception("output bytes differed from input bytes");
    43	        }
    44	    }
    45	    finally
    46	    {
    47	        File.Delete(tempPath);
    48	    }
    49	}
    50	
    51	static void ReturnsFailureWhenMissingFileArgument()
    52	{
    53	    using var output = new MemoryStream();
    54	    using var stderr = new StringWriter();
    55	    var exitCode = SliceApp.Run(Array.Empty<string>(), stderr, output);
    56	    if (exitCode == 0)
    57	    {
    58	        throw new Exception("expected non-zero exit code");
    59	    }
    60	}

